// Use CGAL for robust Voronoi diagram computation via Delaunay triangulation
    std::vector<std::vector<Point2d>> voronoi_cells;
    if (points.empty()) {
        return voronoi_cells;
    }

    // Define CGAL kernel and types
    typedef CGAL::Exact_predicates_inexact_constructions_kernel Kernel;
    typedef Kernel::Point_2 CGALPoint;
    typedef CGAL::Delaunay_triangulation_2<Kernel> Delaunay;
    typedef Delaunay::Face_handle Face_handle;
    typedef Delaunay::Vertex_handle Vertex_handle;
    typedef Delaunay::Edge Edge;
    typedef Kernel::Segment_2 Segment;
    typedef Kernel::Ray_2 Ray;
    typedef Kernel::Line_2 Line;

    // Convert input points to CGAL points
    std::vector<CGALPoint> cgal_points;
    for (const auto& p : points) {
        cgal_points.emplace_back(p.x, p.y);
    }

    // Compute Delaunay triangulation
    Delaunay dt(cgal_points.begin(), cgal_points.end());

    // For each input point, collect Voronoi cell vertices
    for (auto it = dt.finite_vertices_begin(); it != dt.finite_vertices_end(); ++it) {
        std::vector<Point2d> cell_vertices;
        auto circulator = dt.incident_edges(it);
        if (!circulator.is_empty()) {
            auto start = circulator;
            do {
                Face_handle f = circulator->first;
                int i = circulator->second;
                if (dt.is_infinite(f)) {
                    // Handle infinite Voronoi edges (rays)
                    auto v1 = f->vertex(Delaunay::cw(i));
                    auto v2 = f->vertex(Delaunay::ccw(i));
                    auto p1 = v1->point();
                    auto p2 = v2->point();
                    auto midpoint = CGAL::midpoint(p1, p2);
                    auto dual = dt.dual(circulator);
                    if (const Ray* ray = boost::get<Ray>(&dual)) {
                        // Convert ray to a far away point for practical purposes
                        auto direction = ray->direction().vector();
                        auto far_point = ray->source() + direction * 1e6;
                        cell_vertices.emplace_back(far_point.x(), far_point.y());
                    } else if (const Line* line = boost::get<Line>(&dual)) {
                        // This case shouldn't happen for finite vertices
                        auto far_point1 = line->point(0) + line->to_vector() * 1e6;
                        auto far_point2 = line->point(0) - line->to_vector() * 1e6;
                        cell_vertices.emplace_back(far_point1.x(), far_point1.y());
                        cell_vertices.emplace_back(far_point2.x(), far_point2.y());
                    }
                } else {
                    // Finite Voronoi edge (segment)
                    auto dual = dt.dual(circulator);
                    if (const Segment* seg = boost::get<Segment>(&dual)) {
                        cell_vertices.emplace_back(seg->source().x(), seg->source().y());
                    }
                }
            } while (++circulator != start);
        }

        // Remove duplicate vertices (can happen due to numerical precision)
        std::sort(cell_vertices.begin(), cell_vertices.end(), [](const Point2d& a, const Point2d& b) {
            return std::make_pair(a.x, a.y) < std::make_pair(b.x, b.y);
        });
        cell_vertices.erase(std::unique(cell_vertices.begin(), cell_vertices.end()), cell_vertices.end());

        // Order vertices in counter-clockwise order (optional but useful)
        if (!cell_vertices.empty()) {
            auto center = std::accumulate(cell_vertices.begin(), cell_vertices.end(), Point2d{0, 0},
                [](const Point2d& a, const Point2d& b) { return Point2d{a.x + b.x, a.y + b.y}; });
            center.x /= cell_vertices.size();
            center.y /= cell_vertices.size();

            std::sort(cell_vertices.begin(), cell_vertices.end(), [&center](const Point2d& a, const Point2d& b) {
                return std::atan2(a.y - center.y, a.x - center.x) < std::atan2(b.y - center.y, b.x - center.x);
            });
        }

        voronoi_cells.push_back(std::move(cell_vertices));
    }

    return voronoi_cells;

